"""Public service terms, with seller identity supplied by the operator."""
from hashlib import sha256
from html import escape
import json

from fastapi.responses import HTMLResponse

from .config import get_settings

VERSION = '2026-10-22-v3'
FIELDS = ('seller_legal_name','seller_tax_id','seller_address','seller_phone','seller_bank_details','seller_support_email')
OPTIONAL_FIELDS = ('seller_backup_email','seller_registration_number','seller_registration_date','seller_okpo')


def identity(settings):
    return {field: getattr(settings,field,'').strip() for field in (*FIELDS,*OPTIONAL_FIELDS)}


def missing(settings):
    seller=identity(settings)
    return [field.upper() for field in FIELDS if not seller[field]]


def version(settings):
    fingerprint=sha256(json.dumps(identity(settings),sort_keys=True,ensure_ascii=False).encode()).hexdigest()[:16]
    return VERSION+'-'+fingerprint


def snapshot(settings, period_months=1):
    return {'version':version(settings),'seller':identity(settings),'payment':'one-off','period':'calendar-year' if period_months==12 else 'calendar-month','period_months':period_months,'currency':'KGS'}


def page(kind, settings):
    seller=identity(settings)
    labels={'offer':'Условия использования и публичная оферта','privacy':'Политика конфиденциальности',
            'refunds':'Отмена подписки и возврат оплаты','payment':'Как оплатить Oimo','contacts':'Продавец и контакты'}
    name=escape(seller['seller_legal_name'] or 'Продавец будет указан до начала приёма оплаты')
    email=escape(seller['seller_support_email'])
    contact=f'<a href="mailto:{email}">{email}</a>'
    backup=escape(seller['seller_backup_email'])
    contact_options=contact+(f' (резервный адрес: <a href="mailto:{backup}">{backup}</a>)' if backup and backup!=email else '')
    registration=''.join(f'<dt>{label}</dt><dd>{escape(seller[field])}</dd>' for field,label in (
      ('seller_registration_number','Регистрационный номер ИП'),('seller_registration_date','Дата регистрации'),('seller_okpo','ОКПО')) if seller[field])
    common=f'''<section><h2>Продавец и связь</h2><dl><dt>Наименование</dt><dd>{name}</dd>
    <dt>ИНН продавца</dt><dd>{escape(seller['seller_tax_id']) or 'Будет опубликован'}</dd>{registration}
    <dt>Адрес</dt><dd>{escape(seller['seller_address']) or 'Будет опубликован'}</dd>
    <dt>Телефон</dt><dd>{escape(seller['seller_phone']) or 'Будет опубликован'}</dd>
    <dt>Email</dt><dd>{contact_options}</dd><dt>Банковские реквизиты</dt><dd>{escape(seller['seller_bank_details']) or 'Будут опубликованы'}</dd></dl></section>'''
    texts={
      'offer':f'''<p>Эти условия описывают предоставление доступа к сервису на <a href="/">сайте Oimo</a>. Продавец — {name}. Заказчик — владелец зарегистрированного аккаунта компании.</p>
      <h2>Услуга</h2><p>Oimo предоставляет удалённый доступ к программе для управления заведением: меню, кассой, складом, производством, сотрудниками и управленческими отчётами. Состав функций зависит от тарифа. Фискализация и услуги банковского эквайринга для гостей заведения в подписку автоматически не включаются.</p>
      <h2>Пробный доступ</h2><p>После самостоятельной регистрации предоставляются 14 дней пробного доступа для одного заведения. Регистрация не привязывает банковскую карту и не запускает списания.</p>
      <h2>Тариф и срок</h2><p>Действующие цены указаны в сомах на <a href="/#pricing">странице тарифов</a> и в <a href="/billing">разделе подписки</a>. Перед оплатой заказчик выбирает срок и видит окончательную сумму. Один платёж оплачивает один календарный месяц или год (12 календарных месяцев) текущего тарифа и действующий лимит заведений, указанный в заказе. Годовая стоимость показывается целиком и списывается одним платежом. Смена формата и расширение лимита согласуются отдельно.</p>
      <p>Новый оплаченный период начинается после действующего пробного или оплаченного периода, а при отсутствии доступа — с момента подтверждения оплаты. В месяце без соответствующего числа окончание приходится на последний день месяца; год с 29 февраля заканчивается 28 февраля следующего невисокосного года. Точные даты отображаются в разделе подписки.</p>
      <h2>Оплата и получение доступа</h2><p>Оплата производится через защищённую страницу Freedom Pay. Oimo не запрашивает номер карты и CVC. Подписка продлевается после проверки серверного подтверждения оплаты. Получение услуги электронное: доступ предоставляется в том же аккаунте; доставка физических товаров не требуется. При задержке подтверждения обновите статус в разделе подписки или свяжитесь с поддержкой.</p>
      <p>Оплата разовая. Регулярные списания и автопродление не включены. После истечения срока рабочие функции блокируются; владельцу остаётся доступ к оплате подписки.</p>
      <h2>Правила работы</h2><p>Заказчик отвечает за законность вводимых данных, доступы сотрудников, конфиденциальность пароля и корректность собственного учёта. Для синхронизации нужен интернет. Автономная работа кассы доступна после подготовки онлайн и в пределах выданного срока. Совместимость оборудования подтверждается проверкой на устройстве заказчика.</p>
      <p>Плановые работы и исправления могут временно влиять на доступность сервиса. При длительной невозможности использовать оплаченные функции заказчик вправе обратиться за перерасчётом или возвратом.</p>
      <h2>Отмена, возвраты и обращения</h2><p>Применяется <a href="/legal/refunds">политика отмены и возврата</a>. Обращения направляются на {contact}. Обязательные права сторон по применимому законодательству сохраняются.</p>
      <h2>Принятие условий</h2><p>Перед оплатой заказчик отмечает согласие с этой редакцией условий. Согласие, сумма, срок, тариф и реквизиты продавца фиксируются в заказе. Изменение цен или условий не меняет стоимость и срок уже созданного заказа. Персональные данные обрабатываются по <a href="/legal/privacy">политике конфиденциальности</a>.</p>''',
      'privacy':f'''<p>Ответственный за обработку данных аккаунта — {name}. Контакт по вопросам персональных данных: {contact}.</p>
      <h2>Какие данные используются</h2><p>Имя, email, телефон, сведения о компании и заведениях, данные сотрудников, сведения об учёте, IP-адреса и параметры сеансов. Пароли хранятся в виде хеша. Реквизиты банковской карты и CVC вводятся на стороне платёжного провайдера; Oimo их не хранит.</p>
      <h2>Для чего</h2><p>Создание аккаунта, предоставление функций сервиса, разграничение доступа, обработка оплаты, поддержка, отправка системных сообщений и предотвращение злоупотреблений. Автоматическая рекламная рассылка при регистрации не подключается.</p>
      <h2>Обработка и поставщики</h2><p>Для работы используются инфраструктура Render, сервисы DNS и почты Cloudflare, а для обработки платежей — Freedom Pay. Данные передаются в объёме, необходимом для соответствующей задачи. Инфраструктура может находиться за пределами страны пользователя; обращение в поддержку позволяет уточнить применяемые сервисы.</p>
      <p>Заказчик, загружающий данные своих сотрудников и клиентов, обеспечивает правомерность их передачи и доступ только уполномоченных сотрудников.</p>
      <h2>Cookies и локальное хранение</h2><p>Защищённые cookies используются для входа. Настройки интерфейса и подготовленные данные кассы могут храниться в браузере; очередь автономных продаж сохраняется на устройстве до синхронизации. Очистка браузера может удалить неотправленные локальные данные.</p>
      <h2>Хранение и права</h2><p>Данные сохраняются для работы аккаунта, исполнения обязательств и разрешения обращений. Сведения об оплатах и резервные копии могут сохраняться после отключения аккаунта в объёме, необходимом для обязательств и требований закона. Запросы на доступ, исправление и удаление данных направляются на {contact}; в запросе укажите аккаунт и суть обращения, без паролей и CVC.</p>''',
      'refunds':f'''<h2>Отмена</h2><p>Автоматических списаний нет. Чтобы не продлевать подписку, достаточно не оплачивать следующий период. До окончания уже оплаченного срока доступ сохраняется.</p>
      <h2>Основания возврата</h2><p>До начала оплаченного периода можно запросить полный возврат. После начала периода можно запросить возврат за неиспользованную часть пропорционально оставшемуся времени. Ошибочные повторные оплаты и невозможность пользоваться оплаченной услугой из-за подтверждённого сбоя рассматриваются отдельно. Обязательные права покупателя сохраняются.</p>
      <h2>Как подать запрос</h2><p>В <a href="/billing">разделе подписки</a> у оплаченного заказа выберите «Запросить возврат» либо напишите на {contact}. Укажите email аккаунта, номер заказа, дату, сумму и причину. Номер карты целиком, CVC и пароль не требуются.</p>
      <h2>Рассмотрение и перечисление</h2><p>Продавец рассматривает обращение в течение 10 рабочих дней и сообщает решение по email. При одобрении возврат оформляется через Freedom Pay на исходный способ оплаты. Срок зачисления зависит от банка и платёжной системы. Отправка заявки сама по себе не означает, что возврат выполнен. При возврате за неиспользованный период срок доступа корректируется по согласованному решению.</p>''',
      'payment':'''<p>Oimo оплачивается в сомах (KGS) разовым платежом за один календарный месяц или год (12 месяцев). Год оплачивается целиком одним платежом. Доступные цены показаны на <a href="/#pricing">странице тарифов</a>.</p>
      <ol><li>Войдите как владелец компании и откройте <a href="/billing">«Подписка и оплата»</a>.</li><li>Выберите месяц или год, проверьте тариф, полную сумму и условия; подтвердите согласие с офертой.</li><li>Перейдите на платёжную страницу Freedom Pay и выберите доступный способ оплаты. Реквизиты карты вводятся на стороне Freedom Pay.</li><li>Вернитесь в Oimo и проверьте статус. После подтверждения платежа появятся новые даты доступа.</li></ol>
      <p>Повторное нажатие кнопки при незавершённой оплате возвращает к существующему заказу. Если деньги списаны, а статус ещё не обновлён, нажмите «Проверить оплату»; повторно оплачивать тот же заказ не нужно.</p>
      <p>Автопродление и списания без вашего действия не подключены. Доступность способов оплаты определяется подключением магазина и показана на странице Freedom Pay. Возвраты описаны <a href="/legal/refunds">отдельно</a>.</p>
      <p>Планируемые способы приёма оплаты — банковские карты Visa, Mastercard и Элкарт. Способы будут доступны после подключения магазина и подтверждения их платёжным провайдером.</p>
      <div style="display:flex;align-items:center;gap:24px;flex-wrap:wrap" aria-label="Платёжные системы Freedom Pay"><img src="/vendor/payment-logos/visa.svg" alt="Visa" width="70" height="38"><img src="/vendor/payment-logos/mastercard.svg" alt="Mastercard" width="70" height="45"><img src="/vendor/payment-logos/elkart.svg" alt="Элкарт" width="90" height="42"></div>''',
      'contacts':'<p>Oimo — сервис управления столовыми, кафе и ресторанами. По вопросам доступа, оплаты и возвратов обращайтесь по контактам ниже.</p>',
    }
    title=labels[kind]
    field_labels={'SELLER_LEGAL_NAME':'наименование продавца','SELLER_TAX_ID':'ИНН продавца','SELLER_ADDRESS':'адрес продавца','SELLER_PHONE':'рабочий телефон','SELLER_BANK_DETAILS':'банковские реквизиты','SELLER_SUPPORT_EMAIL':'email поддержки'}
    absent=missing(settings)
    draft=f'<aside role="status">Проект документа. Для публикации осталось заполнить: {", ".join(field_labels[field] for field in absent)}. До этого этот текст не является предложением оплатить услугу; онлайн-оплата недоступна.</aside>' if absent else ''
    html=f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Oimo</title><link rel="icon" href="/favicon.svg"><style>
    *{{box-sizing:border-box}}body{{margin:0;background:#f8f6f2;color:#302b32;font:16px/1.7 system-ui,sans-serif}}main{{max-width:880px;margin:auto;padding:30px 24px 60px}}nav{{display:flex;gap:18px;flex-wrap:wrap;margin:18px 0 32px}}a{{color:#61425e}}h1{{font-size:clamp(27px,5vw,42px);line-height:1.2}}h2{{font-size:21px;margin-top:30px}}aside{{padding:18px;background:#fff0d5;border-radius:12px}}dd{{margin:0 0 12px;white-space:pre-line;overflow-wrap:anywhere}}dt{{font-size:13px;color:#746575}}small{{color:#746575}}</style><link rel="stylesheet" href="/ui-theme.css?v=8"></head><body data-ui="legal"><main><a href="/">← Oimo</a><nav><a href="/legal/offer">Условия</a><a href="/legal/privacy">Конфиденциальность</a><a href="/legal/refunds">Возвраты</a><a href="/legal/payment">Оплата</a><a href="/legal/contacts">Контакты</a></nav>{draft}<h1>{title}</h1><small>Редакция {VERSION}</small>{texts[kind]}{common}</main></body></html>'''
    return HTMLResponse(html,headers={'Cache-Control':'no-store'})


def install(app):
    def endpoint_for(kind):
        def endpoint():
            return page(kind,get_settings())
        return endpoint
    for kind in ('offer','privacy','refunds','payment','contacts'):
        app.add_api_route('/legal/'+kind,endpoint_for(kind),methods=['GET'],include_in_schema=False)
